
UPDATE tournaments
SET
  description       = '$30 entry ($5 to break & run pot, $5 green fee, $20 to prize fund). $100 added at 20 players, $150 added at 32. Game type: lagger''s choice between 9-Ball, 10-Ball, and Semi-Fast 8-Ball. 10-Ball break & run contest on 9ft Diamond table. New Aces & 8s contest. Chip system: H6 & below = 4 chips, H7 = 3 chips. Races: H4 & below = race to 2, H5 = race to 3, H6 = race to 4, H7 = race to 5. 2 side pot options: $10 and $20. Semi-Fast 8 rules: rack like diagram, alternating break, RYO, must hit head ball on break, must take what you make if only one category. Can''t win or lose on break. After break, tap rules. No pros or known road players. Winner or split 2 weeks in a row = sit out one week. Every Friday 7PM. Located at Krome Billiards, North Little Rock AR.',
  phone_number      = NULL,
  game_type         = 'other',
  tournament_format = 'chip-tournament'
WHERE id = 265;
